                                    break;
                            }
                        }
                    }
                    position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte());
                }
                break;
            default:
                break;
        }
        buf.readerIndex(endIndex);
    }

    // Ensure battery level is set correctly if not already set
    if (position.getAttributes().get(Position.KEY_BATTERY) == null) {
        if (position.getAttributes().containsKey(Position.KEY_BATTERY_LEVEL)) {
            position.set(Position.KEY_BATTERY, position.getAttributes().get(Position.KEY_BATTERY_LEVEL));
        } else if (position.getAttributes().containsKey(Position.KEY_BATTERY_VOLTAGE)) {
            position.set(Position.KEY_BATTERY, position.getAttributes().get(Position.KEY_BATTERY_VOLTAGE));
        }
    }

    return position;
}

