                } else {
                    int mark = buf.readUnsignedByte();
                    if (mark == 0x7C) {
                        while (buf.readerIndex() < endIndex) {
                            int extendedType = buf.readUnsignedByte();
                            int extendedLength = buf.readByte();
                            switch (extendedType) {
                                case 0x01:
                                    long alarms = buf.readUnsignedInt();
                                    if (BitUtil.check(alarms, 0)) {
                                        position.set(Position.KEY_ALARM, Position.ALARM_ACCELERATION);
                                    }
                                    if (BitUtil.check(alarms, 1)) {
                                        position.set(Position.KEY_ALARM, Position.ALARM_BRAKING);
                                    }
                                    if (BitUtil.check(alarms, 2)) {
                                        position.set(Position.KEY_ALARM, Position.ALARM_CORNERING);
                                    }
                                    if (BitUtil.check(alarms, 3)) {
                                        position.set(Position.KEY_ALARM, Position.ALARM_ACCIDENT);
                                    }
                                    if (BitUtil.check(alarms, 4)) {
                                        position.set(Position.KEY_ALARM, Position.ALARM_TAMPERING);
                                    }
                                    break;
                                default:
                                    buf.skipBytes(extendedLength);
                                    break;
                            }
                        }
                    }
                    position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte());
                }
                break;
            default:
                break;
        }
        buf.readerIndex(endIndex);
    }

    // Ensure battery level is set if not set already
    if (!position.hasAttribute(Position.KEY_BATTERY_LEVEL) && position.hasAttribute(Position.KEY_BATTERY)) {
        position.set(Position.KEY_BATTERY_LEVEL, position.getDouble(Position.KEY_BATTERY) * 10);
    }

    return position;
}

