private Date readDate(ByteBuf buf, Object timezoneObject) {
    int year = buf.readUnsignedByte() + 2000; // Assuming the year is stored in the format of 00-99 and 2000 is added to get the full year
    int month = buf.readUnsignedByte() - 1; // Months are 0-based in Java
    int day = buf.readUnsignedByte();
    int hour = buf.readUnsignedByte();
    int minute = buf.readUnsignedByte();
    int second = buf.readUnsignedByte();

    Calendar calendar = Calendar.getInstance();
    if (timezoneObject instanceof TimeZone) {
        calendar.setTimeZone((TimeZone) timezoneObject);
    }
    calendar.set(year, month, day, hour, minute, second);
    calendar.set(Calendar.MILLISECOND, 0);

    return calendar.getTime();
}

